// Checkout conversion fix: ensure paidEvents increment on successful payment
const { logRevenueEvent } = require('./revenue-tracker');

module.exports = function(req, res, next) {
  const originalSend = res.send;
  res.send = function(body) {
    if (res.statusCode === 200 && req.path === '/api/checkout') {
      logRevenueEvent({ type: 'paid', amount: req.body?.amount || 0 });
    }
    return originalSend.call(this, body);
  };
  next();
};
